    n = 0
    for i, c in enumerate(s):
        n += -vals[c] if i + 1 < len(s) and vals[c] < vals[s[i + 1]] else vals[c]
    if not 1 <= n <= 3999:
        return False
    table = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]
